const storage=(()=>{
  const mem=new Map();
  const fallback={getItem:k=>mem.has(k)?mem.get(k):null,setItem:(k,v)=>mem.set(k,String(v)),removeItem:k=>mem.delete(k),clear:()=>mem.clear()};
  try{const s=window.localStorage;const k='__cultiva_storage_test__';s.setItem(k,'1');s.removeItem(k);return s}catch(e){return fallback}
})();
