const assessmentQuestions=[["Histoire","Quel événement de 1618 est généralement considéré comme le déclencheur de la guerre de Trente Ans ?",["La défenestration de Prague","La bataille de Lépante","La Fronde","Le siège de Vienne"],0,2],["Histoire","Quel empereur byzantin est associé à la compilation du Corpus juris civilis au VIe siècle ?",["Justinien Ier","Héraclius","Basile II","Constantin XI"],0,3],["Histoire","Quel traité de 1713 règle une partie majeure de la guerre de Succession d’Espagne ?",["Le traité d’Utrecht","Le traité de Tilsit","Le traité de Ryswick","Le traité de Campo-Formio"],0,3],["Géographie","Le territoire de Cabinda est une enclave appartenant à quel pays ?",["Angola","Namibie","Gabon","République du Congo"],0,2],["Géographie","Quel détroit relie directement la mer Noire à la mer de Marmara ?",["Le Bosphore","Les Dardanelles","Le détroit de Kertch","Le détroit d’Ormuz"],0,3],["Géographie","Quel pays est traversé à la fois par l’équateur et le tropique du Capricorne ?",["Brésil","Indonésie","Kenya","Équateur"],0,3],["Économie","Dans sa formulation traditionnelle de court terme, la courbe de Phillips relie principalement…",["Inflation et chômage","Dette publique et croissance","Taux de change et balance commerciale","Productivité et démographie"],0,2],["Économie","Une « trappe à liquidité » désigne une situation où…",["La politique monétaire devient moins efficace malgré des taux très bas","Les banques ne détiennent plus aucune réserve","La monnaie cesse d’être convertible","L’inflation dépasse mécaniquement la croissance"],0,3],["Économie","Par rapport à l’indice des prix à la consommation, le déflateur du PIB se distingue notamment parce qu’il…",["Couvre la production intérieure et sa composition peut varier","Ne mesure que les biens importés","Exclut les services","Utilise toujours un panier fixe de biens"],0,3],["Finance","Toutes choses égales par ailleurs, une obligation de duration plus élevée est généralement…",["Plus sensible aux variations de taux d’intérêt","Moins sensible au risque de taux","Toujours moins risquée au crédit","Insensible à sa maturité"],0,2],["Finance","La prime de risque actions correspond le plus souvent à…",["L’excès de rendement attendu des actions sur un actif sans risque","La différence entre dividende et bénéfice","Le coût comptable des capitaux propres","L’écart entre deux indices boursiers"],0,3],["Finance","Une courbe des taux inversée signifie généralement que…",["Les taux courts sont supérieurs aux taux longs","Les taux longs sont toujours négatifs","Toutes les maturités offrent le même taux","Les obligations longues n’ont plus de risque de taux"],0,3],["Politique & institutions","Dans un régime parlementaire, quel mécanisme permet à une assemblée de retirer sa confiance au gouvernement ?",["Une motion de censure","Un référendum abrogatif","Un contrôle de légalité","Une dissolution judiciaire"],0,2],["Politique & institutions","Un contrôle de constitutionnalité « a posteriori » intervient…",["Après l’entrée en vigueur de la loi","Uniquement avant le vote du Parlement","Avant toute discussion parlementaire","Seulement lors d’une élection"],0,3],["Politique & institutions","Dans un bicamérisme asymétrique, cela signifie que…",["Les deux chambres ne disposent pas des mêmes pouvoirs","Les deux chambres sont élues le même jour","Une seule chambre peut proposer des lois","Les deux chambres ont exactement les mêmes compétences"],0,3],["Sciences","Selon le deuxième principe de la thermodynamique, l’entropie d’un système isolé…",["Ne peut pas diminuer spontanément","Est toujours nulle","Diminue à chaque transformation","Est identique à son énergie interne"],0,2],["Sciences","Lors de la méiose, le crossing-over a lieu principalement pendant…",["La prophase I","La métaphase II","L’anaphase II","La télophase I"],0,3],["Sciences","En cosmologie, le décalage spectral vers le rouge des galaxies lointaines est principalement interprété comme un indice de…",["L’expansion de l’Univers","La rotation de la Voie lactée","La contraction du Soleil","La baisse universelle de la température stellaire"],0,3],["Littérature","Quel écrivain est l’auteur de « L’Homme sans qualités » ?",["Robert Musil","Hermann Hesse","Stefan Zweig","Thomas Mann"],0,2],["Littérature","Quel roman de James Joyce est emblématique de l’usage du monologue intérieur et se déroule principalement à Dublin le 16 juin 1904 ?",["Ulysse","Finnegans Wake","Dubliners","Portrait de l’artiste en jeune homme"],0,3],["Littérature","Qui a écrit « La Vie mode d’emploi » ?",["Georges Perec","Raymond Queneau","Michel Butor","Alain Robbe-Grillet"],0,3],["Arts & culture","Quelle technique picturale, associée notamment à Léonard de Vinci, produit des transitions très douces entre les tons ?",["Le sfumato","Le pointillisme","Le dripping","La tempera"],0,2],["Arts & culture","Qui fonde le Bauhaus à Weimar en 1919 ?",["Walter Gropius","Ludwig Mies van der Rohe","Le Corbusier","Alvar Aalto"],0,3],["Arts & culture","« Les Demoiselles d’Avignon » de Picasso est généralement considérée comme une œuvre charnière vers…",["Le cubisme","Le fauvisme","Le futurisme","L’expressionnisme abstrait"],0,3],["Philosophie","Chez Kant, le « noumène » désigne principalement…",["La chose considérée indépendamment de notre expérience sensible","Une sensation immédiate","Une règle morale particulière","Une preuve empirique"],0,2],["Philosophie","Le « voile d’ignorance » est une expérience de pensée associée à…",["John Rawls","Karl Popper","Martin Heidegger","Gilles Deleuze"],0,3],["Philosophie","Quel philosophe distingue notamment les modes d’existence « authentique » et « inauthentique » dans Être et Temps ?",["Martin Heidegger","Bertrand Russell","John Stuart Mill","Auguste Comte"],0,3],["Technologie","Le théorème CAP affirme qu’un système distribué soumis à une partition réseau ne peut garantir simultanément…",["Cohérence et disponibilité","Chiffrement et compression","Mémoire et calcul","Adressage et routage"],0,2],["Technologie","Quel type de structure est couramment utilisé pour indexer efficacement les données sur disque dans les bases de données relationnelles ?",["Un B-tree ou B+ tree","Une pile LIFO","Une liste simplement chaînée","Un automate fini"],0,3],["Technologie","Quel ordre décrit correctement l’établissement classique d’une connexion TCP ?",["SYN → SYN-ACK → ACK","ACK → SYN → FIN","SYN → FIN → ACK","RST → SYN-ACK → SYN"],0,3],["Environnement","Un forçage radiatif positif tend, toutes choses égales par ailleurs, à…",["Réchauffer le système climatique","Refroidir nécessairement les océans","Réduire automatiquement le niveau marin","Supprimer l’effet de serre"],0,2],["Environnement","L’eutrophisation d’un lac est principalement favorisée par…",["Un excès de nutriments comme l’azote et le phosphore","Une baisse de la pression atmosphérique","Une diminution du rayonnement solaire","Une hausse de la salinité marine"],0,3],["Environnement","La circulation thermohaline océanique est principalement liée à des différences de densité dues à…",["La température et la salinité","La longitude et la latitude","La lumière et la profondeur uniquement","La teneur en oxygène uniquement"],0,3],["Cinéma & musique","Le concept de leitmotiv est particulièrement associé aux opéras de…",["Richard Wagner","Claude Debussy","Erik Satie","Gustav Mahler"],0,2],["Cinéma & musique","Au cinéma, une musique est dite « diégétique » lorsqu’elle…",["Provient d’une source appartenant à l’univers de l’histoire","Est ajoutée uniquement au générique","N’a aucun lien avec la scène","Est nécessairement composée avant le tournage"],0,3],["Cinéma & musique","Le manifeste Dogme 95 a notamment été lancé par Lars von Trier et…",["Thomas Vinterberg","Ingmar Bergman","Nicolas Winding Refn","Aki Kaurismäki"],0,3]];
const assessmentNotes={"Histoire":["La défenestration de Prague de 1618 ouvre la crise bohémienne qui se transforme en guerre de Trente Ans.","Sous Justinien Ier, le droit romain est rassemblé et systématisé dans le Corpus juris civilis, qui aura une influence durable sur le droit européen.","Les traités d’Utrecht de 1713 règlent une part essentielle de la guerre de Succession d’Espagne et modifient l’équilibre des puissances européennes."],"Géographie":["Cabinda appartient à l’Angola mais est séparée du reste du pays par une bande de territoire de la République démocratique du Congo.","Le Bosphore relie la mer Noire à la mer de Marmara ; les Dardanelles relient ensuite la mer de Marmara à la mer Égée.","Le Brésil est traversé par l’équateur dans sa partie nord et par le tropique du Capricorne dans sa partie sud."],"Économie":["La courbe de Phillips décrit traditionnellement une relation inverse de court terme entre inflation et chômage, même si cette relation n’est ni stable ni mécanique.","Dans une trappe à liquidité, des taux déjà très faibles limitent la capacité de la politique monétaire conventionnelle à stimuler davantage la demande.","Le déflateur du PIB porte sur la production intérieure et son panier implicite évolue avec la composition du PIB, contrairement à un indice fondé sur un panier de consommation défini."],"Finance":["La duration mesure notamment la sensibilité du prix d’une obligation aux variations de taux : plus elle est élevée, plus le prix réagit fortement.","La prime de risque actions est le rendement supplémentaire attendu pour détenir des actions plutôt qu’un actif considéré comme sans risque.","Une courbe inversée correspond à des rendements à court terme supérieurs aux rendements à long terme sur une partie significative de la courbe."],"Politique & institutions":["Dans un régime parlementaire, une motion de censure est un instrument par lequel une assemblée peut mettre en cause la responsabilité politique du gouvernement.","Un contrôle a posteriori porte sur une loi déjà entrée en vigueur ; en France, la QPC est un exemple de ce type de contrôle.","Le bicamérisme est dit asymétrique lorsque les deux chambres n’ont pas exactement les mêmes compétences ou le même poids dans la procédure institutionnelle."],"Sciences":["Le deuxième principe implique que l’entropie totale d’un système isolé ne diminue pas spontanément.","Le crossing-over se produit pendant la prophase I de la méiose, lorsque les chromosomes homologues sont appariés.","Le décalage vers le rouge cosmologique est l’une des observations majeures associées à l’expansion de l’Univers."],"Littérature":["Robert Musil est l’auteur de L’Homme sans qualités, vaste roman inachevé consacré à l’Empire austro-hongrois finissant.","Ulysse suit principalement Leopold Bloom à Dublin pendant une seule journée, le 16 juin 1904, avec de nombreuses expérimentations de style et de conscience.","Georges Perec publie La Vie mode d’emploi en 1978 ; le roman est construit autour d’un immeuble parisien et de contraintes formelles élaborées."],"Arts & culture":["Le sfumato crée des contours vaporeux et des transitions tonales sans ruptures nettes ; Léonard de Vinci en est l’un des maîtres.","Walter Gropius fonde le Bauhaus en 1919 à Weimar, école majeure de l’architecture, du design et des arts modernes.","Peint en 1907, Les Demoiselles d’Avignon constitue une rupture décisive dans l’œuvre de Picasso et annonce les recherches cubistes."],"Philosophie":["Chez Kant, le noumène renvoie à ce qui est pensé indépendamment de la manière dont il apparaît à notre sensibilité, par opposition au phénomène.","John Rawls utilise le voile d’ignorance pour penser des principes de justice choisis sans connaître sa future position sociale.","Dans Être et Temps, Heidegger analyse notamment l’authenticité et l’inauthenticité comme deux modalités du rapport du Dasein à son existence."],"Technologie":["Le théorème CAP indique qu’en présence d’une partition réseau, un système distribué doit arbitrer entre cohérence forte et disponibilité.","Les B-trees et B+ trees sont adaptés au stockage sur disque car ils réduisent le nombre d’accès nécessaires pour rechercher des clés dans de grands ensembles de données.","Le three-way handshake TCP suit l’ordre SYN, SYN-ACK, puis ACK avant l’échange normal de données."],"Environnement":["Un forçage radiatif positif correspond à un gain net d’énergie dans le système climatique et tend donc à produire un réchauffement.","L’eutrophisation résulte souvent d’apports excessifs d’azote et de phosphore, favorisant des proliférations algales puis une baisse de l’oxygène dissous.","La circulation thermohaline repose sur des différences de densité de l’eau de mer, fortement influencées par la température et la salinité."],"Cinéma & musique":["Wagner emploie systématiquement des leitmotive, motifs musicaux récurrents associés à des personnages, objets ou idées dramatiques.","Une musique diégétique appartient au monde de l’histoire : les personnages peuvent en principe entendre sa source, comme une radio ou un orchestre présent dans la scène.","Le mouvement Dogme 95 est lancé en 1995 par les réalisateurs danois Lars von Trier et Thomas Vinterberg autour d’un manifeste imposant des contraintes de mise en scène."]};
let assessmentLocked=false;
let aq=0,assessmentScores={},assessmentTotals={},assessmentWeighted={},currentQuizCategory=null,assessmentRunQuestions=[],assessmentMistakes=[];
function shuffleAssessmentAnswers(question){const [cat,text,answers,correctIndex,difficulty]=question;const items=answers.map((answer,index)=>({answer,correct:index===correctIndex}));for(let i=items.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[items[i],items[j]]=[items[j],items[i]];}return [cat,text,items.map(x=>x.answer),items.findIndex(x=>x.correct),difficulty]}
function startAssessment(){aq=0;assessmentScores={};assessmentTotals={};assessmentWeighted={};assessmentMistakes=[];assessmentRunQuestions=assessmentQuestions.map(shuffleAssessmentAnswers);document.querySelector('#assessmentIntro').style.display='none';document.querySelector('#assessmentQuiz').style.display='block';renderAssessment()}
function renderAssessment(){assessmentLocked=false;const q=assessmentRunQuestions[aq];document.querySelector('#assessmentCat').textContent=q[0]+' • '+['','Facile','Intermédiaire','Difficile'][q[4]];document.querySelector('#assessmentCount').textContent=`${aq+1} / ${assessmentRunQuestions.length}`;document.querySelector('#assessmentProgress').style.width=`${(aq/assessmentRunQuestions.length)*100}%`;document.querySelector('#assessmentQuestion').textContent=q[1];document.querySelector('#assessmentAnswers').innerHTML=q[2].map((a,i)=>`<button class="assessment-answer" data-action="assessment-answer" data-index="${i}">${String.fromCharCode(65+i)} — ${escHtml(a)}</button>`).join('');document.querySelector('#assessmentFeedback').style.display='none';document.querySelector('#assessmentNext').style.display='none'}
const learningTips={
'Histoire':'Replace ce fait dans une chronologie : avant, pendant, après. Le contexte rend la date beaucoup plus facile à retenir.',
'Géographie':'Visualise le lieu sur une carte et relie-le à un pays, une région ou un voisin : la mémoire spatiale aide énormément.',
'Économie':'Repère toujours la chaîne cause → effet : quelle variable bouge, pourquoi, et quelles conséquences cela entraîne.',
'Finance':'Distingue le produit, le risque et le rendement : trois repères suffisent souvent à éviter les confusions.',
'Politique & institutions':'Identifie l’institution, son pouvoir et sa limite : c’est le trio le plus utile pour comprendre le fonctionnement politique.',
'Sciences':'Relie le terme à son mécanisme : ce qui se passe, à quelle échelle, et avec quel effet observable.',
'Littérature':'Associe auteur, œuvre, époque et courant : ces quatre repères construisent une mémoire durable.',
'Arts & culture':'Associe l’œuvre à son créateur, son époque et son mouvement artistique pour créer un repère visuel solide.',
'Philosophie':'Cherche l’idée centrale derrière le nom : une thèse claire se retient mieux qu’une citation isolée.',
'Technologie':'Relie chaque terme à sa fonction concrète : entrée, traitement, stockage, réseau ou sortie.',
'Environnement':'Pense en système : cause, impact, rétroaction et échelle de temps.',
'Cinéma & musique':'Associe créateur, œuvre, date approximative et style : le cerveau retient mieux un petit réseau qu’un nom seul.'
};
function escHtml(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]||c))}
function detailedNoteHtml(cat,question,correct,note){
  const tip=learningTips[cat]||'Relie la réponse à un exemple concret et reformule-la avec tes propres mots.';
  return `<div class="note-main">${escHtml(note)}</div><div class="note-context"><strong>À retenir</strong> · ${escHtml(correct)}<br>${escHtml(tip)}</div>`;
}
function localDeepDive(ctx){
  const promptByCat={
    'Histoire':'Quel événement proche dans le temps peux-tu relier à cette réponse ?',
    'Géographie':'Peux-tu situer ce lieu mentalement et citer un voisin ou une région proche ?',
    'Économie':'Quel serait l’effet inverse si le mécanisme décrit changeait de sens ?',
    'Finance':'Quel risque principal associerais-tu à ce concept ou à cet instrument ?',
    'Politique & institutions':'Quelle institution exerce ou contrôle ce pouvoir dans un système comparable ?',
    'Sciences':'Comment expliquerais-tu ce mécanisme à quelqu’un en une seule phrase ?',
    'Littérature':'À quelle époque ou à quel courant rattacherais-tu cette œuvre ou cet auteur ?',
    'Arts & culture':'Quel autre artiste ou mouvement pourrais-tu rapprocher de ce repère ?',
    'Philosophie':'Quelle idée opposée pourrait-on confronter à cette thèse ?',
    'Technologie':'Dans quel usage concret rencontres-tu ce concept ?',
    'Environnement':'Quelle conséquence indirecte ce phénomène peut-il provoquer ?',
    'Cinéma & musique':'Quelle autre œuvre du même créateur ou de la même époque connais-tu ?'
  };
  const challenge=promptByCat[ctx.cat]||'Peux-tu reformuler cette idée avec tes propres mots ?';
  return `<h4>🧠 Deep dive</h4><p>${escHtml(ctx.note)}</p><p><strong>Connexion mentale</strong> · ${escHtml(learningTips[ctx.cat]||'Relie ce fait à un exemple que tu connais déjà.')}</p><div class="think-box">${escHtml(challenge)}</div><div class="ai-state">Analyse locale · prêt pour une connexion IA plus tard</div>`;
}
let currentLearnMore=null;
function showLearnMore(targetId,btn){
  const target=document.getElementById(targetId);if(!target||!currentLearnMore)return;
  if(target.classList.contains('show')){target.classList.remove('show');btn.textContent='En savoir plus →';return;}
  target.textContent='';
  // Sécurité: aucune réponse HTML distante n'est injectée dans le DOM. Le deep-dive reste local
  // tant qu'un backend authentifié avec un format de données strict n'est pas déployé.
  target.innerHTML=localDeepDive(currentLearnMore);
  target.classList.add('show');btn.textContent='Réduire ↑';
}
function assessmentAnswer(i){if(assessmentLocked)return;assessmentLocked=true;const q=assessmentRunQuestions[aq],cat=q[0],difficulty=q[4],ok=i===q[3];assessmentTotals[cat]=(assessmentTotals[cat]||0)+1;assessmentWeighted[cat]=(assessmentWeighted[cat]||0);if(ok){assessmentScores[cat]=(assessmentScores[cat]||0)+1;assessmentWeighted[cat]+=difficulty;}const buttons=[...document.querySelectorAll('.assessment-answer')];buttons.forEach((b,n)=>{b.disabled=true;if(n===q[3])b.classList.add('correct')});if(!ok)buttons[i].classList.add('wrong');const catIndex=assessmentRunQuestions.slice(0,aq+1).filter(x=>x[0]===cat).length-1;const note=(assessmentNotes[cat]||[])[catIndex]||`À retenir : ${q[2][q[3]]}`;if(!ok){const reviewQ=[q[1],[...q[2]],q[3],note,q[4]];assessmentMistakes=pushRecentMistake(assessmentMistakes,cat,reviewQ)}const fb=document.querySelector('#assessmentFeedback');fb.className='assessment-feedback '+(ok?'good':'bad');const correct=q[2][q[3]];currentLearnMore={cat,question:q[1],correct,note};fb.innerHTML=`<b>${ok?'✓ Clean !':'✕ Nope'}</b>${!ok?`Réponse : <strong>${escHtml(correct)}</strong><br>`:''}${detailedNoteHtml(cat,q[1],correct,note)}<button class="learn-more-btn" data-action="learn-more" data-target="assessmentDeepDive">En savoir plus →</button><div class="deep-dive" id="assessmentDeepDive"></div>`;fb.style.display='block';const next=document.querySelector('#assessmentNext');next.textContent=aq===assessmentRunQuestions.length-1?'Score →':'Next →';next.style.display='block'}
function nextAssessment(){aq++;if(aq<assessmentRunQuestions.length)renderAssessment();else finishAssessment()}
function labelFor(m){return m>=80?'Expert':m>=60?'Avancé':m>=40?'Intermédiaire':m>=20?'Novice':'Débutant'}
function finishAssessment(){document.querySelector('#assessmentQuiz').style.display='none';document.querySelector('#assessmentResult').style.display='block';let mastery={};Object.keys(categoryMeta).forEach(c=>{const correct=assessmentScores[c]||0,weighted=assessmentWeighted[c]||0,maxWeighted=assessmentQuestions.filter(q=>q[0]===c).reduce((sum,q)=>sum+q[4],0);const placementRatio=(correct/3)*.45+(weighted/maxWeighted)*.55;mastery[c]=Math.min(70,Math.round(placementRatio*70))});const general=Math.min(7,Math.round((Object.values(mastery).reduce((a,b)=>a+b,0)/Object.keys(mastery).length)/10*10)/10);const total=Object.values(assessmentScores).reduce((a,b)=>a+b,0);document.querySelector('#resultSummary').innerHTML=`<b>${total}/${assessmentRunQuestions.length}</b> · Level <b>${general}/10</b> 🔥`;document.querySelector('#resultGrid').innerHTML=Object.keys(categoryMeta).map(c=>`<div class="result-item"><b>${categoryMeta[c]} ${c}</b><small>${labelFor(mastery[c])} • ${mastery[c]}% • ${(mastery[c]/10).toFixed(1)}/10</small></div>`).join('');saveProfile(mastery,general,total)}
function saveProfile(mastery,general,total){const today=new Date().toISOString().slice(0,10);storage.setItem('cultivaAssessment',JSON.stringify({scores:assessmentScores,totals:assessmentTotals,mastery,general,totalQuestions:total,date:new Date().toISOString(),practiceAnswers:0,wrongHistory:assessmentMistakes.slice(0,20),activity:{[today]:{answers:0,sessions:0,general}},streak:1,bestStreak:1,lastActive:today}))}
function enterCultiva(){document.querySelector('#onboarding').classList.add('hidden');renderProfile()}
function getProfile(){try{return JSON.parse(storage.getItem('cultivaAssessment'))}catch(e){return null}}
function reviewQuestionId(cat,q){return `${cat}|${q&&q[0]||''}|${q&&q[1]&&q[1][q[2]]||''}`}
function pushRecentMistake(list,cat,q){const id=reviewQuestionId(cat,q),item={id,cat,q,at:Date.now()};return [item,...(list||[]).filter(x=>x&&x.id!==id)].slice(0,20)}
function recordMistake(cat,q){let p=getProfile();if(!p)return;p.wrongHistory=pushRecentMistake(p.wrongHistory,cat,q);storage.setItem('cultivaAssessment',JSON.stringify(p));renderReviewPanel()}
function getReviewItems(){const p=getProfile();return ((p&&p.wrongHistory)||[]).filter(x=>x&&x.cat&&Array.isArray(x.q)).slice(0,20)}
function renderReviewPanel(){const panel=document.querySelector('#reviewPanel');if(!panel)return;const items=getReviewItems(),count=items.length,btn=document.querySelector('#reviewBtn');document.querySelector('#reviewCount').textContent=count;document.querySelector('#reviewSubtitle').textContent=count?`${count} erreur${count>1?'s':''} récente${count>1?'s':''}`:'Rien à revoir';if(btn)btn.disabled=!count;const cats=[];items.forEach(x=>{if(!cats.includes(x.cat))cats.push(x.cat)});document.querySelector('#reviewTags').innerHTML=cats.slice(0,4).map(c=>`<span class="review-tag">${categoryMeta[c]||'✦'} ${escHtml(c)}</span>`).join('')}
function startReviewQuiz(){const items=getReviewItems();if(!items.length)return;currentCategoryPage=null;quizSession=shuffled(items.map(x=>({cat:x.cat,q:x.q,review:true})));quizIndex=0;quizCorrect=0;currentQuizMode='review';document.querySelector('#modal').classList.add('show');renderQuizQuestion()}
function dayDiff(a,b){const A=new Date(a+'T00:00:00'),B=new Date(b+'T00:00:00');return Math.round((B-A)/86400000)}
function touchActivity(answerInc=0,sessionInc=0){let p=getProfile();if(!p)return;const today=new Date().toISOString().slice(0,10);p.activity=p.activity||{};p.activity[today]=p.activity[today]||{answers:0,sessions:0,general:p.general||0};p.activity[today].answers+=answerInc;p.activity[today].sessions+=sessionInc;p.activity[today].general=p.general||0;if(p.lastActive!==today){const gap=p.lastActive?dayDiff(p.lastActive,today):99;p.streak=gap===1?(p.streak||0)+1:1;p.bestStreak=Math.max(p.bestStreak||0,p.streak);p.lastActive=today}else{p.streak=p.streak||1;p.bestStreak=Math.max(p.bestStreak||0,p.streak)}storage.setItem('cultivaAssessment',JSON.stringify(p))}
function updateMastery(cat,correct,difficulty=2){
  let p=getProfile();if(!p||!p.mastery||p.mastery[cat]===undefined)return;
  const old=p.mastery[cat];
  // Progression volontairement lente : il faut confirmer son niveau sur plusieurs sessions.
  // Les questions difficiles rapportent davantage et les gains diminuent à haut niveau.
  const gainBase={1:.5,2:.72,3:1.0}[difficulty]||.72;
  const lossBase={1:1.2,2:1.0,3:.82}[difficulty]||1;
  let gainFactor=Math.max(.22,1-old/135);
  let lossFactor=.78+old/150;
  // À partir de 7/10, chaque dixième doit être confirmé par beaucoup plus de réponses difficiles.
  if(old>=70)gainFactor*=.55;
  if(old>=80)gainFactor*=.65;
  if(old>=90)gainFactor*=.55;
  if(old>=70)lossFactor*=1.12;
  if(old>=80)lossFactor*=1.15;
  const delta=correct?gainBase*gainFactor:-lossBase*lossFactor;
  p.mastery[cat]=Math.max(0,Math.min(100,Math.round((old+delta)*10)/10));
  p.general=Math.round((Object.values(p.mastery).reduce((a,b)=>a+b,0)/Object.keys(p.mastery).length)/10*10)/10;
  p.practiceAnswers=(p.practiceAnswers||0)+1;
  p.adaptiveEvidence=p.adaptiveEvidence||{};
  p.adaptiveEvidence[cat]=(p.adaptiveEvidence[cat]||0)+1;
  storage.setItem('cultivaAssessment',JSON.stringify(p));touchActivity(1,0);renderProfile();
}
function renderProfile(){const p=getProfile();if(!p||!p.mastery)return;document.querySelector('.pill').innerHTML=`🧠 Level <b>${p.general}/10</b> &nbsp; • &nbsp; ${labelFor(p.general*10)}`;document.querySelector('#categoryGrid').innerHTML=Object.keys(categoryMeta).map((c,i)=>{let m=Math.round(p.mastery[c]);return `<article class="cat" data-action="open-category" data-category="${escHtml(c)}"><div class="icon" style="background:${colors[i%colors.length]}">${categoryMeta[c]}</div><h3>${escHtml(c)}</h3><p>${labelFor(m)} • ${(m/10).toFixed(1)}/10</p><div class="progress"><i style="width:${m}%"></i></div></article>`}).join('');const avg=Math.round(p.general*10);document.querySelector('#grindPanel').innerHTML=`<h3>Ton grind</h3><p>XP live · Niveau auto</p><div class="stats"><div class="stat"><b>${p.general}/10</b><small>Level</small></div><div class="stat"><b>${avg}%</b><small>Mastery</small></div><div class="stat"><b>${p.practiceAnswers||0}</b><small>Réponses</small></div><div class="stat"><b>${allPracticeQuestions().length}+</b><small>Questions</small></div></div>`;document.querySelector('#streakCount').textContent=`${p.streak||0} jour${(p.streak||0)>1?'s':''}`;document.querySelector('#bestStreak').textContent=p.bestStreak||0;renderReviewPanel();renderHistory('month')}
function historyBuckets(days,bucketSize){const p=getProfile(),act=(p&&p.activity)||{},out=[];const now=new Date();for(let start=days-1;start>=0;start-=bucketSize){let sum=0,count=0,latest=null;for(let j=0;j<bucketSize && start-j>=0;j++){const d=new Date(now);d.setDate(now.getDate()-(start-j));const key=d.toISOString().slice(0,10);if(act[key]){sum+=act[key].answers||0;count++;latest=act[key].general??latest}}out.push({value:sum,general:latest})}return out}
function renderHistory(range='month',btn=null){document.querySelectorAll('.history-tab').forEach(x=>x.classList.remove('active'));if(btn)btn.classList.add('active');else document.querySelector('.history-tab')?.classList.add('active');const cfg=range==='year'?{days:365,bucket:14,label:'1 an'}:range==='six'?{days:180,bucket:7,label:'6 mois'}:{days:30,bucket:1,label:'30 jours'};const data=historyBuckets(cfg.days,cfg.bucket),max=Math.max(1,...data.map(x=>x.value));document.querySelector('#historyRangeLabel').textContent=cfg.label;document.querySelector('#historyChart').innerHTML=data.map(x=>`<div class="history-bar" title="${x.value} réponses" style="height:${Math.max(4,Math.round(x.value/max*100))}%"></div>`).join('');const total=data.reduce((a,b)=>a+b.value,0),active=data.filter(x=>x.value>0).length,p=getProfile();document.querySelector('#historySummary').innerHTML=`<div><b>${total}</b><small>Réponses</small></div><div><b>${active}</b><small>Jours actifs</small></div><div><b>${p?p.general:0}/10</b><small>Level actuel</small></div>`}
function initAssessment(){
  storage.removeItem('cultivaOnlineQuestionCache');
  const resetKey='cultivaReset_10k_v1';
  if(!storage.getItem(resetKey)){
    storage.removeItem('cultivaAssessment');
    storage.removeItem('cultivaSeenQuestions');
    storage.setItem(resetKey,'1');
  }
  if(storage.getItem('cultivaAssessment')){document.querySelector('#onboarding').classList.add('hidden');renderProfile()}
}
const colors=['#eeeaff','#e8f7ff','#eafff5','#fff4df','#fff0f4','#eaf8ff','#f5edff','#fff0e8'];
function renderDefaultCats(){document.querySelector('#categoryGrid').innerHTML=Object.keys(categoryMeta).map((c,i)=>`<article class="cat"><div class="icon" style="background:${colors[i%colors.length]}">${categoryMeta[c]}</div><h3>${c}</h3><p>Locked 🔒</p><div class="progress"><i style="width:0%"></i></div></article>`).join('')}
renderDefaultCats();
