function questionId(cat,q){let h=2166136261;const str=cat+'|'+q[0]+'|'+q[1].join('~')+'|'+q[2];for(const ch of str){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return 'q'+(h>>>0).toString(36)}
function getSeen(){try{return JSON.parse(storage.getItem('cultivaSeenQuestions')||'[]')}catch{return []}}
function markSeen(cat,q){const id=questionId(cat,q),seen=getSeen();if(!seen.includes(id)){seen.push(id);if(seen.length>12000)seen.splice(0,seen.length-12000);storage.setItem('cultivaSeenQuestions',JSON.stringify(seen))}}
function preferUnseen(items){const seen=new Set(getSeen()),fresh=items.filter(x=>!seen.has(questionId(x.cat,x.q)));return fresh.length?fresh:items}

let quizSession=[],quizIndex=0,quizCorrect=0,quizLocked=false;
function allPracticeQuestions(){return Object.entries(practiceBank).flatMap(([cat,qs])=>qs.map(q=>({cat,q}))) }
function shuffled(a){return [...a].sort(()=>Math.random()-.5)}
function targetDifficulty(mastery){if(mastery<25)return 1;if(mastery<70)return 2;return 3}
function adaptiveDifficultyWeights(mastery,challenge=false){
  let w;
  if(mastery<20) w=[.75,.25,0];
  else if(mastery<40) w=[.45,.5,.05];
  else if(mastery<55) w=[.12,.63,.25];
  else if(mastery<70) w=[0,.45,.55];
  else if(mastery<80) w=[0,.08,.92];
  else w=[0,.02,.98];
  if(challenge){w=[0,w[0]+w[1]*.12,w[2]+w[1]*.88];const sum=w.reduce((a,b)=>a+b,0);w=w.map(x=>x/sum)}
  return w;
}
function rollDifficulty(mastery,challenge=false){const w=adaptiveDifficultyWeights(mastery,challenge),r=Math.random();if(r<w[0])return 1;if(r<w[0]+w[1])return 2;return 3}
function highLevelQuestionScore(item){const q=item.q,text=q[0]||'',difficulty=q[4]||2;let score=difficulty*25+Math.min(18,text.length/7);if(/association|chronolog|mécanisme|conséquence|implique|caractérise|explique|relation|énoncé|parmi|principalement|toutes choses/i.test(text))score+=14;if(text.split(/\s+/).length>=15)score+=7;return score}
function pickAdaptiveQuestion(name,challenge=false,excludeIds=new Set()){
  const p=getProfile(),m=(p&&p.mastery&&p.mastery[name])||0,target=rollDifficulty(m,challenge);
  const all=(practiceBank[name]||[]).map(q=>({cat:name,q})).filter(x=>!excludeIds.has(questionId(name,x.q)));
  const unseen=preferUnseen(all),source=unseen.length?unseen:all;
  if(m>=70){const ranked=[...source].sort((a,b)=>highLevelQuestionScore(b)-highLevelQuestionScore(a)),share=challenge?.12:(m>=85?.18:.35),elite=ranked.slice(0,Math.max(1,Math.ceil(ranked.length*share)));return shuffled(elite)[0]}
  const exact=source.filter(x=>(x.q[4]||2)===target);
  if(exact.length)return shuffled(exact)[0];
  return shuffled(source).sort((a,b)=>Math.abs((a.q[4]||2)-target)-Math.abs((b.q[4]||2)-target))[0];
}

let currentCategoryPage=null,currentQuizMode='normal';
function openCategory(name){
  if(!Object.prototype.hasOwnProperty.call(categoryMeta,name))return;
  currentCategoryPage=name;
  const p=getProfile(),m=Math.round((p&&p.mastery&&p.mastery[name])||0),d=targetDifficulty(m);
  document.querySelector('#homeView').classList.add('hidden');
  const page=document.querySelector('#categoryPage');page.classList.add('show');
  page.innerHTML=`<div class="cat-hero"><div class="cat-top"><div><span style="font-size:38px">${categoryMeta[name]}</span><h1>${name}</h1><p>Ton niveau · Ton run</p></div><button class="back-btn" data-action="close-category">← Back</button></div><div class="level-card"><div class="level-row"><b>${labelFor(m)} · ${(m/10).toFixed(1)}/10</b><span>${m}% mastery</span></div><div class="level-bar"><i style="width:${m}%"></i></div></div></div><div class="adaptive-note">✦ Niveau auto · ${d===1?'easy → medium':d===2?'medium → hard':'hard focus'} · 10K bank</div><div class="category-actions"><article class="category-action"><h3>⚡ Smart run</h3><p>5 questions · Niveau auto · ${name.toLowerCase()}</p><button class="btn" data-action="adaptive-quiz" data-category="${escHtml(name)}">GO →</button></article><article class="category-action"><h3>🎯 Hard mode</h3><p>3 questions · Ça pique</p><button class="btn" data-action="adaptive-quiz" data-category="${escHtml(name)}" data-hard="1">TRY ME →</button></article></div>`;
  window.scrollTo({top:0,behavior:'smooth'});
}
function closeCategory(){currentCategoryPage=null;document.querySelector('#categoryPage').classList.remove('show');document.querySelector('#homeView').classList.remove('hidden');window.scrollTo({top:0,behavior:'smooth'})}
function adaptivePool(name,challenge=false,count=5){
 const picked=[],used=new Set();
 for(let i=0;i<count;i++){const item=pickAdaptiveQuestion(name,challenge,used);if(!item)break;picked.push(item);used.add(questionId(name,item.q))}
 return picked;
}
function openAdaptiveQuiz(name,challenge=false){if(!Object.prototype.hasOwnProperty.call(categoryMeta,name))return;currentQuizMode='normal';quizSession=adaptivePool(name,challenge,challenge?3:5);quizIndex=0;quizCorrect=0;document.querySelector('#modal').classList.add('show');renderQuizQuestion()}
const dailyKnowledge=[
['Pourquoi les années bissextiles existent-elles ?','Une année solaire dure environ 365,2422 jours, légèrement plus que 365 jours. Ajouter généralement un 29 février tous les quatre ans permet de garder notre calendrier aligné avec les saisons, avec quelques exceptions pour les années séculaires.'],
['Le plus grand désert du monde n’est pas le Sahara','Un désert se définit surtout par la très faible quantité de précipitations qu’il reçoit. Avec cette définition, l’Antarctique est le plus grand désert de la planète, devant l’Arctique et le Sahara.'],
['Le mot « algorithme » vient d’un nom propre','Le terme « algorithme » dérive du nom latinisé du mathématicien persan Al-Khwarizmi, qui vécut aux VIIIe et IXe siècles. Ses travaux ont joué un rôle majeur dans la diffusion des méthodes de calcul et de l’algèbre.'],
['La lumière du Soleil met du temps à nous atteindre','La lumière voyage à environ 300 000 kilomètres par seconde. Malgré cette vitesse immense, elle met environ 8 minutes et 20 secondes pour parcourir la distance moyenne entre le Soleil et la Terre.'],
['Une frontière peut traverser un bâtiment','À Baarle, entre la Belgique et les Pays-Bas, la frontière forme un véritable puzzle d’enclaves et peut traverser des rues et des bâtiments. Dans certains cas, l’adresse nationale d’une maison dépend même de la position de sa porte d’entrée.']
];
function openDailyKnowledge(){const d=new Date(),idx=(d.getFullYear()*372+d.getMonth()*31+d.getDate())%dailyKnowledge.length,item=dailyKnowledge[idx];document.querySelector('#dailyTitle').textContent=item[0];document.querySelector('#dailyText').textContent=item[1];document.querySelector('#dailyModal').classList.add('show')}
function closeDailyKnowledge(){document.querySelector('#dailyModal').classList.remove('show')}
function openRandomPage(){
 const p=getProfile(); document.querySelector('#homeView').classList.add('hidden');
 const page=document.querySelector('#categoryPage');page.classList.add('show');
 page.innerHTML=`<div class="cat-hero"><div class="cat-top"><div><span style="font-size:38px">🎲</span><h1>Mode chaos 🎲</h1><p>Tout mixé · Niveau auto</p></div><button class="back-btn" data-action="close-category">← Back</button></div><div class="level-card"><div class="level-row"><b>Level · ${p?p.general:0}/10</b><span>12 moods</span></div><div class="level-bar"><i style="width:${p?Math.round(p.general*10):0}%"></i></div></div></div><div class="adaptive-note">✦ Full mix · 10K bank · Zéro routine</div><div class="category-actions"><article class="category-action"><h3>🎲 Full run</h3><p>10 questions · Full send</p><button class="btn" data-action="random-run" data-count="10">GO →</button></article><article class="category-action"><h3>⚡ Quick run</h3><p>5 questions · Fast XP</p><button class="btn" data-action="random-run" data-count="5">5Q →</button></article></div>`;
 window.scrollTo({top:0,behavior:'smooth'});
}
function startRandomAdaptive(count=10){
 currentQuizMode='normal';
 const cats=shuffled(Object.keys(practiceBank)),selected=[],used=new Set();
 for(let i=0;i<count;i++){
   const cat=cats[i%cats.length],item=pickAdaptiveQuestion(cat,false,used);
   if(item){selected.push(item);used.add(questionId(cat,item.q))}
 }
 quizSession=shuffled(selected);quizIndex=0;quizCorrect=0;
 if(!quizSession.length)return;
 document.querySelector('#modal').classList.add('show');renderQuizQuestion();
}
function openQuiz(name){
  currentQuizMode='normal';
  {const bank=practiceBank[name]||practiceBank['Histoire'];quizSession=shuffled(bank).map(q=>({cat:name,q}))}
  quizIndex=0;quizCorrect=0;document.querySelector('#modal').classList.add('show');renderQuizQuestion();
}
function renderQuizQuestion(){
  quizLocked=false;const item=quizSession[quizIndex],q=item.q;currentQuizCategory=item.cat;
  document.querySelector('#quizTag').textContent=item.cat;
  document.querySelector('#quizCount').textContent=`${quizIndex+1}/${quizSession.length}`;
  document.querySelector('#quizScore').textContent=`${quizCorrect} pts`;
  document.querySelector('#quizProgress').style.width=`${(quizIndex/quizSession.length)*100}%`;
  document.querySelector('#quizQuestion').textContent=q[0];
  const display=q[1].map((text,i)=>({text,correct:i===q[2]})).sort(()=>Math.random()-.5);
  window._quizDisplay=display;
  document.querySelector('#quizAnswers').innerHTML=display.map((a,i)=>`<button class="answer" data-action="quiz-answer" data-index="${i}">${String.fromCharCode(65+i)} — ${escHtml(a.text)}</button>`).join('');
  document.querySelector('#explain').style.display='none';document.querySelector('#quizNext').style.display='none';
}
function answer(el,choice){if(quizLocked)return;quizLocked=true;const item=quizSession[quizIndex],q=item.q,display=window._quizDisplay||q[1].map((text,i)=>({text,correct:i===q[2]})),ok=!!display[choice].correct;markSeen(currentQuizCategory,q);if(ok)quizCorrect++;else recordMistake(currentQuizCategory,q);const buttons=[...document.querySelectorAll('#quizAnswers .answer')];buttons.forEach((b,i)=>{b.disabled=true;if(display[i]&&display[i].correct)b.classList.add('correct')});if(!ok)el.classList.add('wrong');const correct=display.find(x=>x.correct)?.text||q[1][q[2]],note=q[3]||`La bonne réponse est ${correct}`;currentLearnMore={cat:currentQuizCategory,question:q[0],correct,note};const ex=document.querySelector('#explain');ex.innerHTML=`<b>${ok?'✓ Clean !':'✕ Nope'}</b><br>${!ok?`Réponse : <strong>${escHtml(correct)}</strong><br>`:''}${detailedNoteHtml(currentQuizCategory,q[0],correct,note)}<button class="learn-more-btn" data-action="learn-more" data-target="quizDeepDive">En savoir plus →</button><div class="deep-dive" id="quizDeepDive"></div>`;ex.style.display='block';document.querySelector('#quizScore').textContent=`${quizCorrect} pts`;updateMastery(currentQuizCategory,ok,q[4]||2);const next=document.querySelector('#quizNext');next.textContent=quizIndex===quizSession.length-1?'Score →':'Next →';next.style.display='block'}
function nextQuizQuestion(){quizIndex++;if(quizIndex<quizSession.length){renderQuizQuestion();return}const pct=Math.round(quizCorrect/quizSession.length*100);document.querySelector('#quizProgress').style.width='100%';document.querySelector('#quizQuestion').textContent=currentQuizMode==='review'?'Révision terminée ↺':'Run terminé 🔥';document.querySelector('#quizAnswers').innerHTML='';document.querySelector('#explain').innerHTML=`<b>${quizCorrect}/${quizSession.length} bonnes — ${pct}%</b><br>${currentQuizMode==='review'?'Erreurs retravaillées 🧠':'XP mis à jour ⚡'}`;document.querySelector('#explain').style.display='block';touchActivity(0,1);const next=document.querySelector('#quizNext');next.textContent='Voir mon level';next.dataset.action='close-quiz';next.style.display='block'}
function closeQuiz(){document.querySelector('#modal').classList.remove('show');document.querySelector('#quizNext').dataset.action='next-quiz';renderProfile();if(currentCategoryPage&&document.querySelector('#categoryPage').classList.contains('show'))openCategory(currentCategoryPage)}
// Fallback anti-clickjacking pour hébergement statique (les vraies protections doivent idéalement être des en-têtes HTTP).
if(window.top!==window.self){document.documentElement.style.display='none';try{window.top.location=window.self.location.href}catch(e){}}

document.addEventListener('click',e=>{
  const el=e.target.closest('[data-action]');if(!el)return;
  const action=el.dataset.action;
  if(action==='start-assessment')startAssessment();
  else if(action==='next-assessment')nextAssessment();
  else if(action==='enter-cultiva')enterCultiva();
  else if(action==='assessment-answer')assessmentAnswer(Number(el.dataset.index));
  else if(action==='open-random')openRandomPage();
  else if(action==='scroll-categories')document.querySelector('#categories')?.scrollIntoView({behavior:'smooth'});
  else if(action==='open-daily')openDailyKnowledge();
  else if(action==='close-daily')closeDailyKnowledge();
  else if(action==='start-review')startReviewQuiz();
  else if(action==='history')renderHistory(el.dataset.range,el);
  else if(action==='open-category')openCategory(el.dataset.category||'');
  else if(action==='close-category')closeCategory();
  else if(action==='adaptive-quiz')openAdaptiveQuiz(el.dataset.category||'',el.dataset.hard==='1');
  else if(action==='random-run')startRandomAdaptive(Math.min(10,Math.max(1,Number(el.dataset.count)||5)));
  else if(action==='quiz-answer')answer(el,Number(el.dataset.index));
  else if(action==='learn-more')showLearnMore(el.dataset.target,el);
  else if(action==='next-quiz')nextQuizQuestion();
  else if(action==='close-quiz')closeQuiz();
});

initAssessment();
document.querySelector('#modal').addEventListener('click' ,e=>{if(e.target.id==='modal')closeQuiz()});
document.querySelector('#dailyModal').addEventListener('click',e=>{if(e.target.id==='dailyModal')closeDailyKnowledge()});